import { defineStore } from 'pinia'
import { ref } from 'vue'
import api from '@/api'

export const useUserStore = defineStore('user', () => {
  const token = ref(localStorage.getItem('token') || '')
  const user = ref(JSON.parse(localStorage.getItem('user') || 'null'))
  const roles = ref(JSON.parse(localStorage.getItem('roles') || '[]'))
  const menus = ref(JSON.parse(localStorage.getItem('menus') || '[]'))
  const permissions = ref(JSON.parse(localStorage.getItem('permissions') || '[]'))

  async function login(username, password, captchaKey, captchaAnswer, rememberMe = false) {
    const res = await api.post('/auth/login', { username, password, captchaKey, captchaAnswer })
    const { token: t, user: u, roles: r, menus: m, permissions: p } = res.data
    token.value = t
    user.value = u
    roles.value = r || []
    menus.value = m || []
    permissions.value = p || []
    localStorage.setItem('token', t)
    localStorage.setItem('user', JSON.stringify(u))
    localStorage.setItem('roles', JSON.stringify(r || []))
    localStorage.setItem('menus', JSON.stringify(m || []))
    localStorage.setItem('permissions', JSON.stringify(p || []))
    if (rememberMe) {
      localStorage.setItem('remember_me', 'true')
    }
    return res
  }

  function isRemembered() {
    return localStorage.getItem('remember_me') === 'true' && !!localStorage.getItem('token')
  }

  function logout() {
    token.value = ''
    user.value = null
    roles.value = []
    menus.value = []
    permissions.value = []
    localStorage.clear()
  }

  return { token, user, roles, menus, permissions, login, logout, isRemembered }
})
